// Verifies that the manually serialized dApp opcodes match the reviewed Tolk ABI.
// The source ABI snapshots are generated by scripts/acton_abi.py from Acton.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const ABI_DIR = 'docs/abi';
const DAPP_FILE = 'website/tonconnect.js';
const ABI_FILES = ['quasar-master.json', 'quasar-defi.json', 'quasar-wallet.json'];

const DAPP_TO_ABI: Record<string, string> = {
    STAKE_QSR: 'Stake',
    UNSTAKE_QSR: 'Unstake',
    CLAIM_STAKE: 'ClaimRewards',
    ADD_LIQUIDITY: 'AddLiquidity',
    REMOVE_LIQUIDITY: 'RemoveLiquidity',
    SWAP_TO_TON: 'SwapToTon',
    SWAP_TO_QSR: 'SwapToQsr',
    CLAIM_FARM: 'ClaimFarmRewards',
    REFUND_PENDING_QSR: 'RefundPendingQsr',
};

type Snapshot = { messages: Array<{ name: string; opcode: string }> };

function abiHeaders(): Map<string, number> {
    const headers = new Map<string, number>();
    for (const file of ABI_FILES) {
        const abi = JSON.parse(readFileSync(join(ABI_DIR, file), 'utf8')) as Snapshot;
        for (const message of abi.messages) {
            headers.set(message.name, Number.parseInt(message.opcode, 16));
        }
    }
    return headers;
}

function main() {
    const source = readFileSync(DAPP_FILE, 'utf8');
    const headers = abiHeaders();
    const failures: string[] = [];
    const block = /const OP = \{([\s\S]*?)\n\};/.exec(source);
    if (!block) throw new Error('dApp ABI check: could not locate the `const OP = { ... }` map');

    const entries = new Map<string, number>();
    for (const [, name, value] of block[1].matchAll(/([A-Z_0-9]+):\s*(\d+)/g)) {
        entries.set(name, Number(value));
    }
    if (entries.size === 0) throw new Error('dApp ABI check: the dApp opcode map is empty');

    for (const [dappName, value] of entries) {
        const abiName = DAPP_TO_ABI[dappName];
        if (!abiName) {
            failures.push(`${dappName}: no ABI mapping registered in DAPP_TO_ABI`);
            continue;
        }
        const header = headers.get(abiName);
        if (header === undefined) {
            failures.push(`${dappName}: ABI message ${abiName} is absent from the reviewed Tolk snapshots`);
        } else if (header !== value) {
            failures.push(`${dappName}: dApp has ${value} (0x${value.toString(16)}) but Tolk ABI has ${header} (0x${header.toString(16)})`);
        }
    }

    const transfer = /const JETTON_TRANSFER_OP = 0x([0-9a-fA-F]+)/.exec(source);
    if (!transfer) {
        failures.push('JETTON_TRANSFER_OP: constant not found (TEP-74 transfer opcode is required)');
    } else {
        const value = Number.parseInt(transfer[1], 16);
        const header = headers.get('TokenTransfer');
        if (header === undefined) failures.push('JETTON_TRANSFER_OP: TokenTransfer not found in Tolk ABI');
        else if (header !== value) failures.push(`JETTON_TRANSFER_OP: dApp has 0x${value.toString(16)} but Tolk ABI has 0x${header.toString(16)}`);
    }

    if (failures.length > 0) throw new Error(`dApp ABI check failed:\n${failures.map((item) => `  - ${item}`).join('\n')}`);
    console.log(`Verified ${DAPP_FILE} against reviewed Tolk ABI (${entries.size} opcodes + TEP-74 transfer)`);
}

try {
    main();
} catch (error) {
    console.error(error instanceof Error ? error.message : error);
    process.exitCode = 1;
}
